python
def frequencyFilesFloorTicket(readings, k):
    a=readings
    out=[]
    counts={}
    for x in a: counts[x]=counts.get(x,0)+1
    for x in sorted(counts): out.append(counts[x])
    return min(out,default=0)


java
class Solution {
  public int frequencyFilesFloorTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Map<Integer,Integer>counts=new TreeMap<>();for(int x:a)counts.merge(x,1,Integer::sum);out.addAll(counts.values());}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
